    const invoiceId=await ctx.db.insert("invoices",{invoiceNumber:`INV-COD-${serial}`,customerId,customerName:"عميل COD",items:[{productId,productName:"منتج COD",quantity:2,unitPrice:50,discount:0,total:100}],subtotal:100,discount:0,tax:0,total:100,netTotal:100,creditedTotal:0,paid,remaining,paymentMethod:remaining?"partial":"prepaid",status:remaining?(paid?"partial":"unpaid"):"paid",notes:`historical-${serial}`,branchId,type:"sale"});
    const accountId=await ctx.db.insert("financialAccounts",{name:`حساب COD ${serial}`,code:`COD-${serial}`,uniqueKey:`cod:${serial}`,type:options.accountType??"cod_clearing",branchId,isActive:options.accountActive??true,currentBalance:0,allowNegative:false,settlementDelayDays:0,createdAt:1,createdBy:`confirmer-${serial}`,updatedAt:1});
