test("COD-29 عزل Manager وShipping",async()=>{
  const e=await confirmationFixture(29,{paid:20}),managerCase=await addConfirmationCase(e,"29-manager",e.branchId),shippingCase=await addConfirmationCase(e,"29-shipping",e.branchId),other=await addConfirmationCase(e,"29-other"),shippingCrossCase=await addConfirmationCase(e,"29-shipping-cross",e.branchId);const otherBranchId=other.branchId;
  await e.raw.run(async ctx=>{await ctx.db.insert("userProfiles",{userId:"manager-29",tokenIdentifier:"manager-29",name:"Manager",role:"manager",branchId:e.branchId,permissions:[],isActive:true});await ctx.db.insert("userProfiles",{userId:"shipping-29",tokenIdentifier:"shipping-29",name:"Shipping",role:"shipping",branchId:e.branchId,permissions:[],isActive:true});});
  const manager=e.raw.withIdentity({subject:"manager-29",tokenIdentifier:"manager-29"}),shipping=e.raw.withIdentity({subject:"shipping-29",tokenIdentifier:"shipping-29"});
  const managerDelivery=await manager.mutation(api.deliveries.createFromOrderInvoice,managerCase.createArgs),shippingDelivery=await shipping.mutation(api.deliveries.createFromOrderInvoice,shippingCase.createArgs),otherDelivery=await e.t.mutation(api.deliveries.createFromOrderInvoice,other.createArgs),shippingCrossDelivery=await shipping.mutation(api.deliveries.createFromOrderInvoice,shippingCrossCase.createArgs);
  for(const [actor,id] of [[manager,managerDelivery],[shipping,shippingDelivery],[e.t,otherDelivery],[shipping,shippingCrossDelivery]] as const)await actor.mutation(api.deliveries.updateStatus,{id,status:"shipped"});
  await manager.mutation(api.deliveries.confirmDelivered,{deliveryId:managerDelivery,codClearingAccountId:managerCase.accountId,date:"2026-07-10",requestId:"تأكيد Manager"});
  let state=await e.raw.run(async ctx=>({delivery:await ctx.db.get(managerDelivery),account:await ctx.db.get(managerCase.accountId),transactions:(await ctx.db.query("financialTransactions").collect()).filter(x=>x.branchId===e.branchId),entries:(await ctx.db.query("customerLedgerEntries").collect()).filter(x=>x.customerId===managerCase.customerId)}));assert.equal(state.delivery?.status,"delivered");assert.equal(state.account?.currentBalance,80);assert.equal(state.transactions.length,1);assert.equal(state.entries.length,1);
  const beforeManagerReject=await e.raw.run(async ctx=>({otherDelivery:await ctx.db.get(otherDelivery),otherAccount:await ctx.db.get(other.accountId),shippingDelivery:await ctx.db.get(shippingDelivery)}));await assert.rejects(manager.mutation(api.deliveries.confirmDelivered,{deliveryId:otherDelivery,codClearingAccountId:other.accountId,date:"2026-07-10",requestId:"manager-other-delivery"}),/فرع/);await assert.rejects(manager.mutation(api.deliveries.confirmDelivered,{deliveryId:shippingDelivery,codClearingAccountId:other.accountId,date:"2026-07-10",requestId:"manager-other-account"}),/فرع/);assert.deepEqual(await e.raw.run(async ctx=>({otherDelivery:await ctx.db.get(otherDelivery),otherAccount:await ctx.db.get(other.accountId),shippingDelivery:await ctx.db.get(shippingDelivery)})),beforeManagerReject);
  await shipping.mutation(api.deliveries.confirmDelivered,{deliveryId:shippingDelivery,codClearingAccountId:shippingCase.accountId,date:"2026-07-10",requestId:"تأكيد Shipping"});
  state=await e.raw.run(async ctx=>({delivery:await ctx.db.get(shippingDelivery),account:await ctx.db.get(shippingCase.accountId),entries:(await ctx.db.query("customerLedgerEntries").collect()).filter(x=>x.customerId===shippingCase.customerId)}));assert.equal(state.delivery?.status,"delivered");assert.equal(state.account?.currentBalance,80);assert.equal(state.entries.length,1);
  const beforeShippingReject=await e.raw.run(async ctx=>({otherDelivery:await ctx.db.get(otherDelivery),otherAccount:await ctx.db.get(other.accountId),localDelivery:await ctx.db.get(shippingCrossDelivery),localAccount:await ctx.db.get(shippingCrossCase.accountId)}));await assert.rejects(shipping.mutation(api.deliveries.confirmDelivered,{deliveryId:otherDelivery,codClearingAccountId:other.accountId,date:"2026-07-10",requestId:"shipping-other-delivery"}),/فرع/);await assert.rejects(shipping.mutation(api.deliveries.confirmDelivered,{deliveryId:shippingCrossDelivery,codClearingAccountId:other.accountId,date:"2026-07-10",requestId:"shipping-other-account"}),/فرع/);assert.deepEqual(await e.raw.run(async ctx=>({otherDelivery:await ctx.db.get(otherDelivery),otherAccount:await ctx.db.get(other.accountId),localDelivery:await ctx.db.get(shippingCrossDelivery),localAccount:await ctx.db.get(shippingCrossCase.accountId)})),beforeShippingReject);
  for(const actor of [manager,shipping]){const page=await actor.query(api.deliveries.listPaginated,{branchId:otherBranchId,paginationOpts:{numItems:20,cursor:null}}),accounts=await actor.query(api.deliveries.accountPicker,{branchId:otherBranchId,purpose:"cod"});assert.equal(page.page.every(x=>x.branchId===e.branchId),true);assert.equal(page.page.some(x=>x._id===otherDelivery),false);assert.equal(accounts.every(x=>x.branchId===e.branchId),true);assert.equal(accounts.some(x=>x._id===other.accountId),false);}
});
