async function settlementFixture(serial:number, codAmounts:number[], options:{delay?:number;destinationBalance?:number}={}) {
  const first=await confirmationFixture(serial,{paid:100-codAmounts[0]});
  if(options.delay) await first.raw.run(async ctx=>ctx.db.patch(first.accountId,{settlementDelayDays:options.delay}));
  const destinationAccountId=await first.raw.run(ctx=>ctx.db.insert("financialAccounts",{name:`Cash ${serial}`,code:`C-${serial}`,uniqueKey:`cash:${serial}`,type:"cash",branchId:first.branchId,isActive:true,currentBalance:options.destinationBalance??0,allowNegative:false,settlementDelayDays:0,createdAt:1,createdBy:"fixture",updatedAt:1}));
  const cases=[{...first,createArgs:first.createArgs}];
  for(let i=1;i<codAmounts.length;i++){const c=await addConfirmationCase(first,`${serial}-${i}`,first.branchId);await first.raw.run(async ctx=>{await ctx.db.patch(c.orderId,{deposit:100-codAmounts[i],appliedDeposit:100-codAmounts[i],remaining:codAmounts[i]});await ctx.db.patch(c.invoiceId,{paid:100-codAmounts[i],remaining:codAmounts[i],status:codAmounts[i]===100?"unpaid":"partial",paymentMethod:codAmounts[i]===100?"cod":"partial"});await ctx.db.patch(c.customerId,{balance:codAmounts[i]});const b=await ctx.db.query("customerBalances").withIndex("by_customer_branch",q=>q.eq("customerId",c.customerId).eq("branchId",first.branchId)).unique();if(b)await ctx.db.patch(b._id,{receivableBalance:codAmounts[i]});});cases.push({...first,...c});}
  const deliveryIds:Id<"deliveries">[]=[];
  for(let i=0;i<cases.length;i++){const c=cases[i],deliveryId=await first.t.mutation(api.deliveries.createFromOrderInvoice,c.createArgs);await first.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});await first.t.mutation(api.deliveries.confirmDelivered,{deliveryId,codClearingAccountId:first.accountId,date:"2026-07-10",requestId:`confirm-${serial}-${i}`});deliveryIds.push(deliveryId);}
  return{...first,destinationAccountId,deliveryIds};
}
async function settlementSnapshot(e:Awaited<ReturnType<typeof settlementFixture>>){return e.raw.run(async ctx=>({deliveries:await ctx.db.query("deliveries").collect(),settlements:await ctx.db.query("codSettlements").collect(),items:await ctx.db.query("codSettlementItems").collect(),transactions:await ctx.db.query("financialTransactions").collect(),movements:await ctx.db.query("financialMovements").collect(),source:await ctx.db.get(e.accountId),destination:await ctx.db.get(e.destinationAccountId),invoices:await ctx.db.query("invoices").collect(),ledger:await ctx.db.query("customerLedgerEntries").collect(),payments:await ctx.db.query("payments").collect()}));}

