test("COD-43 مهلة الإتاحة",async()=>{const e=await settlementFixture(43,[100],{delay:2});const confirmed=await settlementSnapshot(e);const collection=confirmed.movements.find(m=>m.signedAmount===100);assert.equal(collection?.availableAt,"2026-07-12");assert.equal(confirmed.source?.currentBalance,100);const args={deliveryIds:e.deliveryIds,sourceAccountId:e.accountId,destinationAccountId:e.destinationAccountId,feeAmount:0,branchId:e.branchId};const beforeSnapshot=await settlementSnapshot(e);await assert.rejects(e.t.mutation(api.deliveries.createCodSettlement,{...args,date:"2026-07-11",requestId:"early-43"}),/المتاح/);assert.deepEqual(await settlementSnapshot(e),beforeSnapshot);await e.t.mutation(api.deliveries.createCodSettlement,{...args,date:"2026-07-12",requestId:"available-43"});assert.equal((await settlementSnapshot(e)).source?.currentBalance,0);});
test("COD-44 عكس التسوية",async()=>{const e=await settlementFixture(44,[40,60]);const beforeSettlement=await settlementSnapshot(e);const settlementId=await e.t.mutation(api.deliveries.createCodSettlement,{deliveryIds:e.deliveryIds,sourceAccountId:e.accountId,destinationAccountId:e.destinationAccountId,feeAmount:10,date:"2026-07-10",branchId:e.branchId,requestId:"settle-44"});const reversalId=await e.t.mutation(api.deliveries.reverseCodSettlement,{settlementId,reason:"  تصحيح التحويل  ",date:"2026-07-11",requestId:"reverse-44"});const s=await settlementSnapshot(e),row=s.settlements[0],original=s.transactions.find(t=>t.type==="cod_settlement"),reversal=s.transactions.find(t=>t._id===reversalId);assert.equal(row?.status,"reversed");assert.equal(row?.reversalReason,"تصحيح التحويل");assert.equal(row?.reversalDate,"2026-07-11");assert.equal(original?.reversalTransactionId,reversalId);assert.equal(reversal?.originalTransactionId,original?._id);assert.deepEqual(s.movements.filter(m=>m.transactionId===reversalId).map(m=>m.signedAmount).sort((a,b)=>a-b),[-90,100]);assert.equal(s.source?.currentBalance,beforeSettlement.source?.currentBalance);assert.equal(s.destination?.currentBalance,beforeSettlement.destination?.currentBalance);assert.ok(s.deliveries.every(d=>!d.codSettlementId));assert.equal(s.items.length,2);assert.deepEqual(s.invoices,beforeSettlement.invoices);assert.deepEqual(s.ledger,beforeSettlement.ledger);assert.equal(s.payments.length,0);});
test("COD-45 Idempotency العكس",async()=>{const e=await settlementFixture(45,[100]);const settlementId=await e.t.mutation(api.deliveries.createCodSettlement,{deliveryIds:e.deliveryIds,sourceAccountId:e.accountId,destinationAccountId:e.destinationAccountId,feeAmount:10,date:"2026-07-10",branchId:e.branchId,requestId:"settle-45"});const args={settlementId,reason:"retry reversal",date:"2026-07-11",requestId:"reverse-45"};const first=await e.t.mutation(api.deliveries.reverseCodSettlement,args);const afterFirst=await settlementSnapshot(e);const retry=await e.t.mutation(api.deliveries.reverseCodSettlement,args);assert.equal(retry,first);assert.deepEqual(await settlementSnapshot(e),afterFirst);await assert.rejects(e.t.mutation(api.deliveries.reverseCodSettlement,{...args,reason:"different fingerprint"}),/requestId/);assert.deepEqual(await settlementSnapshot(e),afterFirst);await assert.rejects(e.t.mutation(api.deliveries.reverseCodSettlement,{...args,requestId:"different-request-45"}),/طلب مختلف/);assert.deepEqual(await settlementSnapshot(e),afterFirst);});
test("COD-46 Rollback رصيد الوجهة",async()=>{const e=await settlementFixture(46,[100]);const settlementId=await e.t.mutation(api.deliveries.createCodSettlement,{deliveryIds:e.deliveryIds,sourceAccountId:e.accountId,destinationAccountId:e.destinationAccountId,feeAmount:10,date:"2026-07-10",branchId:e.branchId,requestId:"settle-46"});await e.raw.run(async ctx=>{const profile=await ctx.db.query("userProfiles").withIndex("by_token",q=>q.eq("tokenIdentifier","confirmer-46")).unique();if(profile)await ctx.db.patch(profile._id,{permissions:["record_disbursements"]});});await e.t.mutation(api.expenses.create,{title:"صرف فعلي لاحق",category:"تشغيل",amount:20,date:"2026-07-11",accountId:e.destinationAccountId,requestId:"expense-46",branchId:e.branchId});const beforeSnapshot=await settlementSnapshot(e);assert.equal(beforeSnapshot.destination?.currentBalance,70);await assert.rejects(e.t.mutation(api.deliveries.reverseCodSettlement,{settlementId,reason:"رصيد غير كاف",date:"2026-07-12",requestId:"reverse-46"}),/رصيد/);const after=await settlementSnapshot(e);assert.deepEqual(after,beforeSnapshot);assert.equal(after.settlements[0]?.status,"posted");assert.equal(after.items.length,1);assert.ok(after.deliveries[0]?.codSettlementId);});
test("COD-47 عكس التأكيد",async()=>{const e=await confirmationFixture(47,{paid:20});const deliveryId=await e.t.mutation(api.deliveries.createFromOrderInvoice,e.createArgs);await e.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});await e.t.mutation(api.deliveries.confirmDelivered,{deliveryId,codClearingAccountId:e.accountId,date:"2026-07-10",requestId:"confirm-47"});const posted=await codState(e);const reversalId=await e.t.mutation(api.deliveries.reverseConfirmation,{deliveryId,reason:"  رفض المستلم  ",date:"2026-07-11",requestId:"reverse-confirm-47"});const s=await codState(e),confirmation=s.confirmations[0],original=s.transactions.find(t=>t.type==="delivery_cod_collection"),reversal=s.transactions.find(t=>t._id===reversalId);assert.equal(confirmation?.status,"reversed");assert.equal(confirmation?.reversalReason,"رفض المستلم");assert.equal(s.delivery?.status,"shipped");assert.equal(s.delivery?.currentConfirmationId,undefined);assert.equal(s.delivery?.deliveredDate,undefined);assert.equal(s.order?.status,"ready");assert.deepEqual([s.invoice?.paid,s.invoice?.remaining,s.invoice?.status],[20,80,"partial"]);assert.equal(s.account?.currentBalance,0);assert.equal(s.balance?.receivableBalance,80);assert.equal(original?.reversalTransactionId,reversalId);assert.equal(reversal?.originalTransactionId,original?._id);assert.deepEqual(s.movements.map(m=>m.signedAmount).sort((a,b)=>a-b),[-80,80]);assert.equal(s.entries.at(-1)?.receivableDelta,80);assert.deepEqual(s.inventory,posted.inventory);assert.equal(s.product?.stock,posted.product?.stock);assert.equal((await e.raw.run(ctx=>ctx.db.query("codSettlements").collect())).length,0);assert.equal((await e.raw.run(ctx=>ctx.db.query("codSettlementItems").collect())).length,0);});
test("COD-48 مراجعة Legacy بلا payments",async()=>{const e=await confirmationFixture(48,{paid:20});const otherBranchId=await e.raw.run(ctx=>ctx.db.insert("branches",{name:"Legacy other",address:"x",isActive:true}));await e.raw.run(async ctx=>{const base={customerName:"Legacy",customerPhone:"1",city:"x",address:"x",items:[],totalAmount:80,grandTotal:80,paymentMethod:"cod" as const,codAmount:80,prepaidAmount:0,shippingCompany:"Legacy",shippingCost:0,status:"delivered" as const,branchId:e.branchId};await ctx.db.insert("deliveries",{...base,deliveryNumber:"DEL-2025-00001",customerId:e.customerId,invoiceId:e.invoiceId});await ctx.db.insert("deliveries",{...base,deliveryNumber:"DEL-2025-00002",customerId:e.customerId});await ctx.db.insert("deliveries",{...base,deliveryNumber:"DEL-2025-00003",invoiceId:e.invoiceId});await ctx.db.insert("deliveries",{...base,deliveryNumber:"BAD-LEGACY",customerId:e.customerId,invoiceId:e.invoiceId});await ctx.db.insert("deliveries",{...base,deliveryNumber:"DEL-2026-00005",customerId:e.customerId,invoiceId:e.invoiceId,accountingVersion:2});await ctx.db.insert("deliveries",{...base,deliveryNumber:"BAD-OTHER",branchId:otherBranchId});});const snapshot=await e.raw.run(async ctx=>({deliveries:await ctx.db.query("deliveries").collect(),confirmations:await ctx.db.query("deliveryConfirmations").collect(),settlements:await ctx.db.query("codSettlements").collect(),items:await ctx.db.query("codSettlementItems").collect(),transactions:await ctx.db.query("financialTransactions").collect(),movements:await ctx.db.query("financialMovements").collect(),ledger:await ctx.db.query("customerLedgerEntries").collect(),payments:await ctx.db.query("payments").collect()}));const first=await e.t.query(api.deliveries.legacyReview,{branchId:e.branchId});assert.equal(first.length,4);assert.ok(first.some(x=>x.issues.includes("COD مسلم بلا حركة مالية")));assert.ok(first.some(x=>x.issues.includes("بلا فاتورة")));assert.ok(first.some(x=>x.issues.includes("بلا عميل مسجل")));assert.ok(first.some(x=>x.issues.includes("رقم غير متوافق")));assert.ok(first.every(x=>Object.keys(x).every(k=>["deliveryNumber","status","issues","reviewStatus"].includes(k))));assert.ok(first.every(x=>!x.deliveryNumber.includes("OTHER")&&!x.deliveryNumber.includes("00005")));assert.deepEqual(await e.t.query(api.deliveries.legacyReview,{branchId:e.branchId}),first);const after=await e.raw.run(async ctx=>({deliveries:await ctx.db.query("deliveries").collect(),confirmations:await ctx.db.query("deliveryConfirmations").collect(),settlements:await ctx.db.query("codSettlements").collect(),items:await ctx.db.query("codSettlementItems").collect(),transactions:await ctx.db.query("financialTransactions").collect(),movements:await ctx.db.query("financialMovements").collect(),ledger:await ctx.db.query("customerLedgerEntries").collect(),payments:await ctx.db.query("payments").collect()}));assert.deepEqual(after,snapshot);});
test("COD-49 إغلاق المسار القديم وDTO",async()=>{const e=await fixture(49);await assert.rejects(e.t.mutation(api.deliveries.create,{customerName:"x",customerPhone:"1",city:"x",address:"x",items:[],totalAmount:1,paymentMethod:"cod",shippingCompany:"x",shippingCost:0}),/المسار|القديم/);const dto=await e.t.query(api.deliveries.get,{id:e.deliveryId});assert.ok(dto);assert.equal("idempotencyKey" in dto,false);});
